--
-- Table structure for table `slot_allocations`
--

DROP TABLE IF EXISTS `slot_allocations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `slot_allocations` (
  `allocation_id` int NOT NULL AUTO_INCREMENT,
  `voter_id` int NOT NULL,
  `booth_id` int NOT NULL,
  `slot_id` int NOT NULL,
  `event_id` int NOT NULL,
  `booking_reference_token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Cryptographically secure synthetic token',
  `allocation_type` enum('USER_RESERVED','ALGORITHMIC_ALLOCATED','EMERGENCY_WALKIN') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USER_RESERVED',
  `priority_score` int NOT NULL DEFAULT '0' COMMENT 'Calculated priority score factoring category and wait age',
  `queue_token_no` int NOT NULL COMMENT 'Sequential queue number within the specific slot',
  `status` enum('CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','NO_SHOW') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CONFIRMED',
  `booked_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `check_in_time` timestamp NULL DEFAULT NULL,
  `check_out_time` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`allocation_id`),
  UNIQUE KEY `booking_reference_token` (`booking_reference_token`),
  UNIQUE KEY `uq_voter_event_active` (`voter_id`,`event_id`,((case when (`status` in (_utf8mb4'CONFIRMED',_utf8mb4'CHECKED_IN')) then 1 else NULL end))),
  KEY `fk_alloc_booth` (`booth_id`),
  KEY `fk_alloc_event` (`event_id`),
  KEY `idx_alloc_voter` (`voter_id`),
  KEY `idx_alloc_slot_status` (`slot_id`,`status`),
  KEY `idx_alloc_token` (`booking_reference_token`),
  KEY `idx_alloc_queue` (`slot_id`,`queue_token_no`),
