/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_after_allocation_insert` AFTER INSERT ON `slot_allocations` FOR EACH ROW BEGIN
    IF NEW.status = 'CONFIRMED' THEN
        UPDATE `time_slots`
        SET `allocated_count` = `allocated_count` + 1,
            `status` = CASE
                WHEN `allocated_count` + 1 >= `max_capacity` THEN 'FULL'
                ELSE `status`
            END
        WHERE `slot_id` = NEW.slot_id;
    END IF;
END */;;
DELIMITER ;
