/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_after_allocation_update` AFTER UPDATE ON `slot_allocations` FOR EACH ROW BEGIN
    IF OLD.status = 'CONFIRMED' AND NEW.status IN ('CANCELLED', 'NO_SHOW') THEN
        UPDATE `time_slots`
        SET `allocated_count` = GREATEST(0, `allocated_count` - 1),
            `status` = CASE
                WHEN `status` = 'FULL' AND (`allocated_count` - 1) < `max_capacity` THEN 'OPEN'
                ELSE `status`
            END
        WHERE `slot_id` = NEW.slot_id;
    END IF;
END */;;
DELIMITER ;
