DROP TABLE IF EXISTS `time_slots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `time_slots` (
  `slot_id` int NOT NULL AUTO_INCREMENT,
  `booth_id` int NOT NULL,
  `event_id` int NOT NULL,
  `slot_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `max_capacity` int NOT NULL DEFAULT '60',
  `allocated_count` int NOT NULL DEFAULT '0',
  `priority_reserved_capacity` int NOT NULL DEFAULT '15' COMMENT 'Reserved capacity for Priority 1 voters',
  `status` enum('OPEN','FULL','FAST_TRACK_ONLY','CLOSED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`slot_id`),
  UNIQUE KEY `uq_booth_event_timeslot` (`booth_id`,`event_id`,`slot_date`,`start_time`),
  KEY `fk_slots_event` (`event_id`),
  KEY `idx_slots_booth_status` (`booth_id`,`status`),
  KEY `idx_slots_date_time` (`slot_date`,`start_time`),
  CONSTRAINT `fk_slots_booth` FOREIGN KEY (`booth_id`) REFERENCES `polling_booths` (`booth_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_slots_event` FOREIGN KEY (`event_id`) REFERENCES `election_events` (`event_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Discretized time slots with priority quotas per booth';
