--
-- Table structure for table `voters`
--

DROP TABLE IF EXISTS `voters`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `voters` (
  `voter_id` int NOT NULL AUTO_INCREMENT,
  `demo_epic_no` varchar(25) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Synthetic Identifier format: DEM-UK-2026-XXXX',
  `full_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dob` date NOT NULL,
  `gender` enum('MALE','FEMALE','OTHER') COLLATE utf8mb4_unicode_ci NOT NULL,
  `address_zone` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pincode` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `special_category` enum('GENERAL','SENIOR_CITIZEN','PERSON_WITH_DISABILITY','PREGNANT_WOMEN') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GENERAL',
  `priority_level` tinyint NOT NULL DEFAULT '3' COMMENT '1=Highest (Senior/PwD/Pregnant), 2=Elevated, 3=Normal General',
  `simulated_verification_status` enum('UNVERIFIED','SIMULATED_VERIFIED','FLAGGED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNVERIFIED',
  `assigned_booth_id` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`voter_id`),
  UNIQUE KEY `demo_epic_no` (`demo_epic_no`),
  KEY `idx_voters_demo_epic` (`demo_epic_no`),
  KEY `idx_voters_priority` (`priority_level`),
  KEY `idx_voters_category` (`special_category`),
  KEY `idx_voters_booth` (`assigned_booth_id`),
  CONSTRAINT `fk_voters_booth` FOREIGN KEY (`assigned_booth_id`) REFERENCES `polling_booths` (`booth_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=763 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Synthetic voter identities and priority classifications';
/*!40101 SET character_set_client = @saved_cs_client */;

